// Page composition reuses the existing, evidence-backed simulation controls.
const $=id=>document.getElementById(id);
const main=document.querySelector('main');
const sidebar=document.querySelector('.sidebar');sidebar.id='workspace-sidebar';
document.querySelector('.hero').remove();
document.querySelector('.sidebar').innerHTML=`<a class="brand brand-lockup" href="#home" aria-label="潮汐 TIDEFLOW · 返回首页"><img src="./assets/brand-lockup.svg?v=color-2" alt="潮汐 TIDEFLOW" width="166" height="46"></a><p class="brand-caption">OpenFAST 海上风电仿真助手</p><div class="sidebar-rail-label" aria-hidden="true">WORKSPACE<span>07</span></div><nav aria-label="工作空间导航">${[['home','首页'],['model','模型结构'],['engineering','工程原理'],['configure','工况配置'],['analysis','结果分析'],['records','运行与日志'],['reports','分析报告']].map(([key,label],i)=>`<button class="nav" data-page="${key}"><span class="nav-index">0${i+1}</span>${label}${key==='records'?'<b id="run-count">0</b>':''}</button>`).join('')}</nav><div class="side-bottom"><button id="side-ai">AI 助手 <span>↗</span></button><button id="source-open">模型与数据来源 <span>↗</span></button><div><i class="status-dot" id="side-dot"></i><span id="side-mode">正在连接…</span></div><span class="sidebar-version">OPENFAST 5.0.0 / v0.4</span></div>`;
// The toggle remains outside the drawer so it is reachable while collapsed.
const sidebarToggle=document.createElement('button');sidebarToggle.id='sidebar-toggle';sidebarToggle.className='sidebar-toggle';sidebarToggle.setAttribute('aria-controls','workspace-sidebar');document.body.prepend(sidebarToggle);
let sidebarOpen=!matchMedia('(max-width:600px)').matches;
try{const saved=localStorage.getItem('tideflow-sidebar-open');if(saved!==null)sidebarOpen=saved==='true';}catch{}
if(!location.hash||location.hash==='#home')sidebarOpen=false;
function setSidebar(open,{persist=true}={}){if(['engineering','configure'].includes(document.body.dataset.page))open=true;sidebarOpen=open;document.body.classList.toggle('nav-collapsed',!open);sidebarToggle.setAttribute('aria-expanded',String(open));sidebarToggle.setAttribute('aria-label',open?'收起侧边栏':'展开侧边栏');sidebarToggle.innerHTML=open?'<span aria-hidden="true">←</span> 收起':'<img class="toggle-brand" src="./assets/tidal-mark.svg" alt="">导航';sidebar.inert=!open;if(!open&&sidebar.contains(document.activeElement))sidebarToggle.focus();if(persist)try{localStorage.setItem('tideflow-sidebar-open',String(open));}catch{}}
sidebarToggle.onclick=()=>setSidebar(!sidebarOpen);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&sidebarOpen&&!['engineering','configure'].includes(document.body.dataset.page)&&!document.querySelector('dialog[open]')){setSidebar(false);sidebarToggle.focus();}});
setSidebar(sidebarOpen,{persist:false});
const createPage=(id,html)=>{const node=document.createElement('section');node.id='page-'+id;node.className='app-page';node.hidden=true;node.innerHTML=html;main.append(node);return node;};
createPage('home',`<div class="ocean-home"><div class="ocean-shade"></div><div class="home-copy"><span class="eyebrow">OFFSHORE WIND / SIMULATION WORKSPACE</span><h1><span class="heading-line">海上风电</span><span class="heading-line">仿真工作空间</span></h1><p>从工况配置到结果分析，<br>让每一次计算都有可追溯的依据。</p></div><div class="home-project"><span class="kicker">REFERENCE MODEL / 01</span><strong class="model-code"><span class="visually-hidden">OC4</span><svg viewBox="0 0 318 100" aria-hidden="true" focusable="false"><path fill-rule="evenodd" d="M12 4H77Q89 4 89 16V80Q89 92 77 92H12Q0 92 0 80V16Q0 4 12 4ZM22 24V72H67V24Z"/><path d="M190 4H120Q108 4 108 16V80Q108 92 120 92H190V72H130V24H190Z"/><path fill-rule="evenodd" d="M274 4H300V62H315V81H300V94H278V81H210V62ZM239 62H278V24Z"/></svg></strong><h2>半潜式风机</h2><p>NREL 5 MW <span>/</span> OpenFAST</p><button class="text-link" data-page="model">探索模型结构 <span>↗</span></button></div><span class="scene-caption">OC4 视觉示意 / 非海域观测</span></div>`);
createPage('model',`<div class="page-heading"><div><span class="kicker">模型结构</span><h1>OC4 / NREL 5 MW</h1><p>三维结构探索 · 参考模型尺寸与部件说明</p></div><button class="secondary" data-page="engineering">工程原理 →</button></div><div class="model-explorer"><div class="model-visual"><img src="./assets/oc4-model.png" alt="银白色 OC4 半潜式风机与水下系泊系统的视觉示意"><button class="model-hotspot hot-rotor" data-part="rotor" aria-label="查看风轮与塔架">01 <span>风轮与塔架</span></button><button class="model-hotspot hot-platform" data-part="platform" aria-label="查看浮式平台">02 <span>浮式平台</span></button><button class="model-hotspot hot-mooring" data-part="mooring" aria-label="查看系泊系统">03 <span>系泊系统</span></button><div class="selection-brackets" aria-hidden="true"></div><p class="visual-note">结构视觉示意 · 非精确几何 / 点击标记查看构件说明</p></div><aside class="part-inspector"><span class="kicker">COMPONENT EXPLORER</span><div class="part-tabs" role="group" aria-label="选择模型部件"><button data-part="rotor">01</button><button data-part="platform">02</button><button data-part="mooring">03</button></div><span id="part-index">COMPONENT / 02</span><h2 id="part-title"></h2><p id="part-description"></p><dl id="part-specs"></dl><div class="inspector-note">当前原型固定官方结构与控制器。此处用于查看模型组成；计算输入以运行记录及官方模型文件为准。</div><button class="text-link" data-page="configure">基于此模型配置工况 →</button></aside></div><div class="model-summary"><div><span>额定功率</span><strong>5 <small>MW</small></strong></div><div><span>叶轮直径</span><strong>126 <small>m</small></strong></div><div><span>参考水深</span><strong>200 <small>m</small></strong></div><div><span>浮式基础</span><strong>OC4 <small>半潜式</small></strong></div></div>`);
const engineeringPage=createPage('engineering',`<div class="page-heading"><div><span class="kicker">02 / ENGINEERING NOTES</span><h1 class="visually-hidden">工程原理</h1><p>从结构关系理解输入参数、运动响应与计算链路。</p></div><button class="secondary" data-page="model">模型结构 ↗</button></div><div class="engineering-board"><div class="engineering-copy"><span class="kicker">OC4 / NREL 5 MW</span><h2>海风、波浪与<br>浮式系统的响应。</h2><p>气动载荷作用于风轮，波浪载荷作用于浮式平台，系泊系统提供恢复作用。OpenFAST 将结构运动与控制器响应耦合计算。</p><dl><div><dt>参考模型</dt><dd>OC4-DeepCwind</dd></div><div><dt>风机</dt><dd>NREL 5 MW</dd></div><div><dt>水深</dt><dd>200 m</dd></div><div><dt>引擎</dt><dd>OpenFAST 5.0.0</dd></div></dl><button class="engineering-action" data-page="configure">设置风浪工况 →</button><p class="technical-note">线图说明系统组成，不用于尺寸测量。结构、系泊与控制器固定采用官方参考配置。</p></div><div class="technical-drawing"><svg viewBox="0 0 680 650" role="img" aria-label="风轮、浮式平台、系泊系统及风浪载荷结构关系示意图"><defs><pattern id="engineering-grid" width="32" height="32" patternUnits="userSpaceOnUse"><path d="M32 0H0V32" fill="none" stroke="#193e46" stroke-width=".6"/></pattern></defs><rect width="680" height="650" fill="url(#engineering-grid)"/><g fill="none" stroke="#c4d9dd" stroke-width="1.5" stroke-linejoin="round"><path d="M320 395L327 189H336L344 395Z"/><path d="M331 190L311 40L322 40L338 182Z M331 190L469 247L465 258L330 198Z M331 190L221 285L213 277L323 186Z"/><circle cx="331" cy="190" r="9" fill="#e7f1f2"/><path d="M244 411L333 373L425 411L335 450Z M244 411L335 435L425 411 M251 430L335 402L419 430 M253 411L336 454L417 411"/><path d="M235 406V467Q250 480 266 467V406 M235 406Q250 395 266 406Q250 417 235 406 M405 406V467Q420 480 436 467V406 M405 406Q420 395 436 406Q420 417 405 417 M317 441V496Q334 510 351 496V441 M317 441Q334 428 351 441Q334 455 317 441"/><path d="M250 467Q217 566 112 594 M334 501Q334 567 334 594 M421 467Q458 561 572 594" stroke="#71cfcb"/><path d="M85 598H595"/><path d="M95 605l8-7m8 7l8-7m204 7l8-7m8 7l8-7m216 7l8-7m8 7l8-7"/><path d="M40 435Q60 425 80 435T120 435T160 435T200 435T240 435T280 435T320 435T360 435T400 435T440 435T480 435T520 435T560 435T600 435T640 435" stroke="#458d9b"/><path d="M183 45H489 M182 40v10M490 40v10 M608 435V598 M603 435h10M603 598h10" stroke="#547982" stroke-dasharray="3 4"/></g><g fill="#a5c3c9" font-family="Segoe UI,Microsoft YaHei,sans-serif" font-size="13"><text x="290" y="29">叶轮直径 126 m</text><text x="617" y="521" transform="rotate(90 617 521)">参考水深 200 m</text><text x="45" y="422">静水面 / SWL</text><text x="514" y="577">海床 / SEABED</text></g><g fill="none" stroke="#71cfcb" stroke-width="1.5"><path d="M78 181H195m-14-6l14 6-14 6 M78 205H180m-14-6l14 6-14 6 M473 390H552V359 M451 478H536V510"/></g><g fill="#84ddd4" font-family="Segoe UI,Microsoft YaHei,sans-serif" font-size="14"><text x="77" y="164">风 / AERODYNAMICS</text><text x="484" y="348">浮式平台</text><text x="482" y="532">系泊恢复作用</text></g></svg><div class="drawing-legend"><span><i></i> 银白 · 结构</span><span><i></i> 青蓝 · 载荷与系泊</span><span>系统关系示意 / 非工程图纸</span></div></div></div><div class="physics-flow"><article><span>01 / INPUT</span><h3>定义风与波浪</h3><p>稳定风、规则波或 JONSWAP 波浪，记录周期、波高与随机种子。</p></article><article><span>02 / SOLVE</span><h3>执行耦合计算</h3><p>调用真实 OpenFAST，保留输入文件、求解日志与原始输出。</p></article><article><span>03 / REVIEW</span><h3>复核响应与窗口</h3><p>检查功率、平台运动、启动过渡与分析窗口，再进行工况比较。</p></article></div>`);
engineeringPage.dataset.engineeringDesign='atlas';
engineeringPage.querySelector('.page-heading').insertAdjacentHTML('afterend',`<div class="engineering-design-switch" role="group" aria-label="工程原理界面方案"><span>界面方案</span><button type="button" data-engineering-design="atlas" aria-pressed="true">01 工程图册</button><button type="button" data-engineering-design="ocean" aria-pressed="false">02 海洋控制台</button><button type="button" data-engineering-design="signal" aria-pressed="false">03 青白数据站</button></div>`);
engineeringPage.addEventListener('click',event=>{const button=event.target.closest('[data-engineering-design]');if(!button)return;engineeringPage.dataset.engineeringDesign=button.dataset.engineeringDesign;engineeringPage.querySelectorAll('[data-engineering-design]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));});
const config=createPage('configure',`<div class="page-heading"><div><span class="kicker">03 / CONFIGURE</span><h1>定义下一次计算。</h1><p>修改参数后提交真实引擎；已有结果继续保留原始运行参数。</p></div></div><div class="configure-layout"></div>`);
const workspace=$('workspace'),configCard=workspace.querySelector('.config-card'),results=workspace.querySelector('.result-column');
config.querySelector('.configure-layout').append(configCard);
config.querySelector('.configure-layout').insertAdjacentHTML('beforeend',`<aside class="config-explainer"><img src="./assets/oc4-model.png" alt="固定参考模型 OC4 半潜式风机" loading="lazy"><span class="kicker">FIXED REFERENCE MODEL</span><h2>OC4 / NREL 5 MW</h2><p>本次输入仅调整风浪工况及求解设置。结构、控制器与系泊模型采用固定官方配置。</p><div class="config-steps"><span>01 设置工况</span><span>02 提交引擎</span><span>03 检查日志</span><span>04 分析结果</span></div><button class="text-link" data-page="records">查看运行与日志 →</button></aside>`);
const analysis=createPage('analysis',`<div class="page-heading"><div><span class="kicker">04 / RESULTS</span><h1>从响应曲线，走向判断。</h1><p>统计与曲线来自选中记录；比较前请统一窗口并核查变量。</p></div><button class="secondary" data-page="records">选择 / 对比工况 →</button></div>`);
analysis.append(results,$('quality'),$('comparison'));
workspace.remove();
const records=createPage('records',`<div class="page-heading"><div><span class="kicker">05 / RUNS & LOGS</span><h1>每一次运行，都有证据。</h1><p>选择记录、勾选对比工况，或检查引擎原始日志。</p></div><button class="secondary" data-page="analysis">查看选中结果 →</button></div>`);
records.append($('history'),$('diagnostics'));
const reports=createPage('reports',`<div class="page-heading"><div><span class="kicker">06 / REPORT</span><h1>让结论可以复核。</h1><p>从当前工况与勾选的对比记录生成可追溯分析报告。</p></div></div><article class="report-landing"><span class="kicker">TIDEFLOW / ANALYSIS REPORT</span><h2>海上风电<br>仿真分析报告</h2><p>参数与来源 · 窗口统计 · 功率与平台运动<br>日志证据 · 输入哈希 · 判断边界</p><button id="page-report-open" class="primary">预览并导出报告 ↗</button><button class="text-link" data-page="records">先选择对比工况 →</button></article>`);
const banner=$('mode-banner');config.prepend(banner);const footer=document.querySelector('main>footer');main.append(footer);
const parts={rotor:{index:'01',title:'风轮与塔架',text:'三叶片风轮将气动载荷传递至塔架。风机控制与浮式运动共同影响转速与发电功率。',specs:[['参考风机','NREL 5 MW'],['叶轮直径','126 m'],['关注输出','GenPwr / RotSpeed']]},platform:{index:'02',title:'浮式平台',text:'OC4-DeepCwind 半潜式平台通过立柱与支撑构件形成浮式基础，受到波浪载荷并产生纵摇、纵荡等运动。',specs:[['基础类型','半潜式'],['参考水深','200 m'],['关注输出','PtfmPitch / PtfmSurge']]},mooring:{index:'03',title:'系泊系统',text:'悬链线系泊连接浮式平台与海床，为平台运动提供恢复作用。当前原型沿用官方模型中的系泊配置。',specs:[['组成','平台 / 系泊线 / 锚点'],['配置方式','固定官方参考输入'],['检查依据','模型文件与运行日志']]}};
function selectPart(key){const part=parts[key];if(!part)return;$('part-index').textContent='COMPONENT / '+part.index;$('part-title').textContent=part.title;$('part-description').textContent=part.text;$('part-specs').replaceChildren(...part.specs.map(([term,value])=>{const d=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=term;dd.textContent=value;d.append(dt,dd);return d;}));document.querySelectorAll('[data-part]').forEach(b=>{b.classList.toggle('selected',b.dataset.part===key);b.setAttribute('aria-pressed',String(b.dataset.part===key));});document.querySelector('.model-visual').dataset.selection=key;}
const titles={home:'项目首页',model:'模型结构',engineering:'工程原理',configure:'工况配置',analysis:'结果分析',records:'运行与日志',reports:'分析报告'};
function showPage(key,{hash=true}={}){if(!titles[key])key='home';document.body.dataset.page=key;sidebarToggle.hidden=['engineering','configure'].includes(key);if(['engineering','configure'].includes(key))setSidebar(true,{persist:false});else if(key==='home'||matchMedia('(max-width:700px)').matches)setSidebar(false,{persist:false});document.querySelectorAll('.app-page').forEach(p=>p.hidden=p.id!=='page-'+key);document.querySelectorAll('.sidebar [data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===key);if(b.dataset.page===key)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});document.body.dataset.page=key;document.querySelector('.breadcrumb b').textContent=titles[key];document.title=titles[key]+' · 潮汐 TIDEFLOW';if(hash&&location.hash!=='#'+key)history.pushState(null,'','#'+key);window.scrollTo({top:0,behavior:'instant'});}
document.addEventListener('click',e=>{const page=e.target.closest('button[data-page],a[data-page]');if(page)showPage(page.dataset.page);const part=e.target.closest('[data-part]');if(part)selectPart(part.dataset.part);});
window.addEventListener('hashchange',()=>showPage(location.hash.slice(1),{hash:false}));
window.addEventListener('tideflow:navigate',e=>showPage(e.detail));
window.addEventListener('tideflow:render',e=>{$('run-count').textContent=e.detail.count;});
$('side-ai').onclick=()=>$('ai-dialog').showModal();$('page-report-open').onclick=()=>$('report-open').click();
selectPart('platform');showPage(location.hash.slice(1)||'home',{hash:false});
